import { pricingConfig as config, estimateMonthly, money } from './pricing-config.js';
import { icon } from './icons.js';
import { publicNav, publicFooter, btn, esc } from './marketing-ui.js';
const feature = id => config.features.find(f=>f.id===id);
function featureState(f){return `<span class="availability ${f.availability}">${config.availability[f.availability]}</span>`;}
function planCard(p){return `<article class="plan-card ${p.recommended?'recommended':''} reveal"><div class="plan-label">${icon(p.icon,23)}${p.recommended?`<span class="recommended-label">${p.recommended}</span>`:'<span>PROPOSED PLAN</span>'}</div><h2>${p.name}</h2><p class="plan-audience">${p.audience}</p><div class="plan-price">${p.price===null?'<strong>Custom</strong>':p.price===0?'<strong>Free</strong>':`<strong>${money(p.price)}</strong><span>/ member<br>/ month</span>`}</div><p class="plan-description">${p.description}</p>${btn(p.cta,p.price===0?'explore':'waitlist',p.recommended?'primary full':'quiet full','arrow',`data-plan="${p.id}"`)}<div class="plan-inclusions"><h3>${p.id==='starter'?'Start here':p.id==='team'?'Bring the team together':p.id==='business'?'More structure, thoughtfully':'Shape your next chapter'}</h3><ul>${(p.id==='starter'?p.features:p.id==='team'?['chat','calendar','meetings','ai']:p.id==='business'?['chat','permissions','admin']:['governance','support','admin']).map(id=>{const f=feature(id);return `<li>${icon('check',15)}<span>${f.name}${f.availability==='planned'?'<small>Planned</small>':f.availability==='sample'?'<small>Simulated in demo</small>':''}</span></li>`}).join('')}</ul></div></article>`;}
export function pricingPage(){return `<div class="landing pricing-page">${publicNav('pricing')}<main><section class="pricing-hero"><div class="hero-eyebrow"><span></span>${config.stage.toUpperCase()}</div><h1>A little more together.<br><em>A plan for your next chapter.</em></h1><p>Start with your own day. Grow into a shared rhythm.<br>Simple monthly plans, shaped around the way you work.</p><div class="billing-note">${icon('calendar',15)} Monthly billing · USD <span>Preview pricing — no payment required</span></div><div class="pricing-line-art" aria-hidden="true"><svg viewBox="0 0 1000 140"><path d="M0 80H245C320 80 305 10 380 10S450 130 520 130 590 10 660 10 690 80 765 80H1000"/><path d="M0 95H245C320 95 305 25 380 25S450 115 520 115 590 25 660 25 690 95 765 95H1000"/></svg></div></section><section class="pricing-plans" aria-label="Proposed monthly plans">${config.plans.map(planCard).join('')}</section><p class="plan-disclosure">All plans are proposed. Everyone can explore the full demo today.<br>Paid-plan buttons register interest; they do not start a subscription.</p><section class="price-calculator reveal" aria-labelledby="estimate-heading"><div><span class="eyebrow">A LITTLE PLANNING GOES A LONG WAY</span><h2 id="estimate-heading">Your team. Your estimate.</h2><p>See what a month could look like.<br>No sales call. No surprises hidden in the arithmetic.</p></div><div class="calculator-controls"><label>Proposed plan<select id="estimate-plan">${config.plans.map(p=>`<option value="${p.id}" ${p.id==='team'?'selected':''}>${p.name}${p.price!==null?' · '+money(p.price)+(p.price?'/member':''):''}</option>`).join('')}</select></label><div class="seat-label"><label for="estimate-seats">Team members</label><input id="estimate-seats" type="number" min="1" max="${config.maxSeats}" step="1" value="10" aria-describedby="estimate-error"></div><input id="estimate-slider" aria-label="Team size slider" type="range" min="1" max="${config.maxSeats}" value="10"><div class="slider-scale"><span>1 member</span><span>1,000 members</span></div><p id="estimate-error" class="form-error" role="status"></p></div><div class="calculator-result"><span>ESTIMATED MONTHLY TOTAL</span><output id="estimate-total" aria-live="polite">${money(120)}</output><p id="estimate-detail">10 members × $12 per month</p><small>Proposed base price. Taxes and final terms are not yet established.</small><button class="btn primary" id="estimate-cta" data-action="waitlist" data-plan="team">Register Team interest ${icon('arrow',15)}</button></div></section><section class="comparison-section reveal"><div class="section-intro"><div><span class="eyebrow">THE DETAILS, IN THE OPEN</span><h2>A shared foundation.<br>Room to grow.</h2></div><p>Plan columns show proposed packaging.<br>The availability label tells you what exists in today’s prototype.</p></div><div class="comparison-table"><table><caption class="sr-only">Proposed plan features and their current availability</caption><thead><tr><th scope="col">Inside your workspace</th>${config.plans.map(p=>`<th scope="col">${p.name}</th>`).join('')}</tr></thead><tbody>${config.features.map(f=>`<tr><th scope="row"><span>${f.name}</span>${featureState(f)}<small>${f.detail}</small></th>${config.plans.map(p=>`<td>${p.features.includes(f.id)?`<span class="comparison-check">${icon('check',17)}<span class="sr-only">Included in proposed ${p.name} plan</span></span>`:'<span aria-label="Not included">—</span>'}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="mobile-comparison">${config.features.map(f=>`<details><summary><span>${f.name}${featureState(f)}</span>${icon('plus',17)}</summary><p>${f.detail}</p><ul>${config.plans.map(p=>`<li><b>${p.name}</b><span>${p.features.includes(f.id)?'Included in proposed plan':'Not included'}</span></li>`).join('')}</ul></details>`).join('')}</div></section><section class="pricing-faq reveal"><div><span class="eyebrow">GOOD QUESTIONS DESERVE CLEAR ANSWERS</span><h2>A few things<br>worth knowing.</h2><p>Still exploring? The demo is open.<br>Take your time.</p><a class="btn quiet" href="/#app/home">Explore the workspace ${icon('arrow',16)}</a></div><div>${config.faqs.map(([q,a])=>`<details><summary>${q}${icon('plus',18)}</summary><p>${a}</p></details>`).join('')}</div></section><section class="pricing-close reveal"><span class="eyebrow">LESS SWITCHING. MORE SHARED UNDERSTANDING.</span><h2>Find your rhythm.</h2><p>A conversation, a plan, a clearer day. See how it all connects.</p>${btn('Step inside Loop','explore','primary','arrow')}</section></main>${publicFooter()}</div>`;}
export function bindPricing(){const plan=document.querySelector('#estimate-plan'),seats=document.querySelector('#estimate-seats'),slider=document.querySelector('#estimate-slider');if(!plan)return;let frame;function update(source){if(source===slider)seats.value=slider.value;const result=estimateMonthly(plan.value,Number(seats.value)),error=document.querySelector('#estimate-error'),total=document.querySelector('#estimate-total'),cta=document.querySelector('#estimate-cta');error.textContent=result.error||'';seats.setAttribute('aria-invalid',String(!!result.error));if(result.error){total.textContent='—';document.querySelector('#estimate-detail').textContent='Enter a valid team size to see an estimate.';cta.disabled=true;return}cta.disabled=false;slider.value=seats.value;const p=config.plans.find(p=>p.id===plan.value);total.textContent=result.total===null?'Custom':money(result.total);document.querySelector('#estimate-detail').textContent=result.total===null?'A conversation about your organization.':`${result.seats.toLocaleString()} ${result.seats===1?'member':'members'} × ${money(p.price)} per month`;cta.dataset.plan=p.id;cta.textContent=`Register ${p.name} interest`;total.classList.remove('estimate-changed');cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>total.classList.add('estimate-changed'));}plan.addEventListener('change',()=>update(plan));seats.addEventListener('input',()=>update(seats));slider.addEventListener('input',()=>update(slider));}
